<script setup lang="ts">import { ref } from 'vue'; import { onLoad,onShow } from '@dcloudio/uni-app'; const field=ref<'skills'|'summary'>('summary'); const value=ref(''); onLoad(q=>{if(q?.field)field.value=q.field as 'skills'|'summary'}); onShow(()=>{const d=uni.getStorageSync('resume-draft')||{};value.value=d[field.value]||''}); function save(){const d=uni.getStorageSync('resume-draft')||{};d[field.value]=value.value;uni.setStorageSync('resume-draft',d);uni.navigateBack()} function remove(){uni.showModal({title:'确认删除',content:'确定删除此模块的内容吗？',success:({confirm})=>{if(!confirm)return;value.value='';save()}})}</script>
<template><view class="page"><textarea v-model="value" class="textarea" :placeholder="field==='skills'?'如：Vue、TypeScript、数据分析':'请输入个人总结'"/><button class="save" @click="save">完成</button><button v-if="value" class="delete-button" @click="remove">删除此模块</button></view></template>
<style scoped lang="scss">.page{min-height:100vh;padding:18px 16px;background:#f5f6fa}.tip{padding:12px 2px;color:#64748b;font-size:13px;line-height:20px}.textarea{width:100%;height:220px;box-sizing:border-box;padding:14px;border:1px solid #e2e8f0;border-radius:12px;background:#fff;color:#172033;font-size:15px;line-height:24px}.save,.delete-button{height:48px;margin-top:22px;border-radius:24px;line-height:48px}.save{background:#2563eb;color:#fff}.delete-button{border:1px solid #fecaca;background:#fff;color:#ef4444}</style>
